package com.example.bandlink.service;
import com.example.bandlink.entity.*; import com.example.bandlink.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service public class BlockService {private final UserRepository users;private final BlockRepository blocks;private final Clock clock;@org.springframework.beans.factory.annotation.Autowired public BlockService(UserRepository u,BlockRepository b){this(u,b,Clock.systemDefaultZone());}BlockService(UserRepository u,BlockRepository b,Clock c){users=u;blocks=b;clock=c==null?Clock.systemDefaultZone():c;}@Transactional public void block(Long a,Long b){if(a.equals(b))throw new IllegalArgumentException("自分自身はブロックできません");User x=users.findById(a).orElseThrow();User y=users.findById(b).orElseThrow();if(!blocks.existsByBlockerIdAndBlockedId(a,b))blocks.save(new Block(x,y,LocalDateTime.now(clock)));}@Transactional public void unblock(Long a,Long b){blocks.findByBlockerIdAndBlockedId(a,b).ifPresent(blocks::delete);}public java.util.List<Block> list(Long a){return blocks.findByBlockerId(a);}}
